using System;using System.Data;using System.Linq;using System.IO;
namespace Videira {static class DeliveryTests {
 static void Check(bool b,string m){if(!b)throw new Exception("Entrega: "+m);}
 public static void Run(){var db=new Store(Path.Combine(Environment.CurrentDirectory,"work","Delivery-"+Guid.NewGuid()));db.Company["Origem Porto Meira confirmada"]="Sim";Check(db.DeliveryFee("Boa Esperança",false)==7,"tabela");Check(db.DeliveryFee("América",false)==18m&&db.DeliveryFee("america",false)==18m&&db.DeliveryFee("Jd. América",true)==21m,"América corresponde a Jardim América");Check(db.ResolveDeliveryRegion("América")["Região"].ToString()=="Jardim América","nome canônico");bool similar=false;try{db.DeliveryFee("Americana",false);}catch{similar=true;}Check(similar,"não confundir bairro parecido");Check(db.DeliveryFee("Boa Esperança",true)==10,"condomínio");bool failed=false;try{db.DeliveryFee("Não existe",false);}catch{failed=true;}Check(failed,"bairro desconhecido bloqueado");failed=false;try{db.DeliveryFee("Jardim Santa Rita",false);}catch{failed=true;}Check(failed,"tarifa ambígua bloqueada");db.Data.Tables["Produtos"].Rows.Add(1,"X","VINHO","F",50m,80m,10m,"Sim");var cart=new DataTable();cart.Columns.Add("Produto",typeof(int));cart.Columns.Add("Quantidade",typeof(decimal));cart.Columns.Add("Preço",typeof(decimal));cart.Rows.Add(1,1m,80m);int id=db.Quote(cart,"CLIENTE","","Pix",DateTime.Today.AddDays(1),"");db.Atomic(()=>db.SaveQuoteDelivery(id,false,"85854320","Rua de destino 123","Boa Esperança",7));var q=db.Data.Tables["Orçamentos"].Rows.Find(id);Check((decimal)q["Total"]==87&&q["Mensagem"].ToString().Contains("Entrega: R$ 7,00"),"frete no total e mensagem");int sale=db.ConvertQuote(id);var v=db.Data.Tables["Vendas"].Rows.Find(sale);Check((decimal)v["Total"]==87&&(decimal)v["Entrega R$"]==7&&(decimal)v["Resultado"]==29,"repasse do frete sem lucro fictício");db.Cancel(sale);Check((decimal)db.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==10,"cancelar restaura estoque");id=db.Quote(cart,"CLIENTE","","Pix",DateTime.Today.AddDays(1),"");db.Atomic(()=>db.SaveQuoteDelivery(id,true,"","","",0));Check(!db.Data.Tables["Orçamentos"].Rows.Find(id)["Mensagem"].ToString().Contains("Entrega:"),"retirada sem bloco entrega");db.SetupFourRates();Check(db.Data.Tables["Taxas"].Rows.Count==4&&db.Rate("Pix")==0,"quatro taxas e Pix");db.Save();db=new Store(db.Root);Check(db.Data.Tables["Taxas"].Rows.Count==4,"parcelamentos não retornam");db.ImportPortfolio();var market=db.Data.Tables["Mercado"].Rows[1];var p=db.Data.Tables["Produtos"].Rows.Find(market["Produto"]);Check(!(bool)p["Confirmado"],"catálogo não confirmado");int pendingBefore=db.MarketView(true).Rows.Count;db.ConfirmMarketProduct(market);Check(db.MarketView(true).Rows.Count==pendingBefore-1,"confirmado sai do Mercado");var reopened=new Store(db.Root);Check(!reopened.MarketView(true).AsEnumerable().Any(r=>(int)r["Produto"]==(int)p["Id"]),"confirmado não retorna ao reabrir");Check(reopened.Data.Tables["Mercado"].Rows.Find(market["Id"])!=null,"referência preservada");Check((bool)p["Confirmado"]&&(decimal)p["Preço"]>0&&(decimal)p["Estoque"]==1,"confirmar produto com uma unidade inicial");File.AppendAllText(Path.Combine(Environment.CurrentDirectory,"work","test-result.txt"),"\r\nPASS 2.8: entrega, condomínio, bairro desconhecido/ambíguo, orçamento com frete, retirada, conversão financeira, cancelamento, quatro taxas persistentes e confirmação de Mercado.");}
}}
